package org.example.wikimapreader.car;
import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
public final class CarStore {
 private static CarStore instance;
 public static synchronized CarStore get(Context c){if(instance==null)instance=new CarStore(c);return instance;}
 private final AtomicFile file;private JSONObject state;
 private CarStore(Context c){file=new AtomicFile(new File(c.getFilesDir(),"car-data-v1.json"));try{state=new JSONObject(new String(WikiApi.read(file.openRead(),16*1024*1024),StandardCharsets.UTF_8));if(state.optInt("version")!=1)throw new IOException();}catch(Exception e){state=new JSONObject();}}
 private JSONArray array(String k){JSONArray a=state.optJSONArray(k);return a==null?new JSONArray():a;}
 private void save()throws Exception {state.put("version",1);byte[] data=state.toString().getBytes(StandardCharsets.UTF_8);if(data.length>15*1024*1024)throw new IOException("Кэш заполнен");FileOutputStream out=file.startWrite();try{out.write(data);file.finishWrite(out);}catch(Exception e){file.failWrite(out);throw e;}}
 public synchronized JSONArray favorites(){try{return new JSONArray(array("favorites").toString());}catch(Exception e){return new JSONArray();}}
 public synchronized JSONArray sync(JSONArray legacy,JSONArray operations,boolean migrate)throws Exception {JSONObject before=new JSONObject(state.toString());try{Map<String,JSONObject> rows=new LinkedHashMap<>();for(int i=0;i<array("favorites").length();i++){JSONObject p=array("favorites").getJSONObject(i);rows.put(p.optString("source")+":"+p.optLong("id"),p);}if(migrate&&!state.optBoolean("migrated")){for(int i=0;i<legacy.length();i++){JSONObject p=legacy.optJSONObject(i);if(p!=null&&valid(p))rows.putIfAbsent(p.optString("source","wikimapia")+":"+p.getLong("id"),p);}state.put("migrated",true);}JSONObject receipts=state.optJSONObject("receipts");if(receipts==null)receipts=new JSONObject();for(int i=0;i<operations.length();i++){JSONObject op=operations.getJSONObject(i),p=op.getJSONObject("place");String opId=op.optString("opId");if(!opId.isEmpty()&&receipts.optBoolean(opId))continue;if(!opId.isEmpty())receipts.put(opId,true);if(!valid(p))continue;String k=p.optString("source","wikimapia")+":"+p.getLong("id");if(op.optBoolean("remove"))rows.remove(k);else rows.put(k,new JSONObject().put("id",p.getLong("id")).put("title",p.optString("title","Объект #"+p.getLong("id"))).put("source",p.optString("source","wikimapia")));}state.put("receipts",receipts);state.put("favorites",new JSONArray(rows.values()));save();return favorites();}catch(Exception e){state=before;throw e;}}
 private static boolean valid(JSONObject p){return p.optLong("id")>0&&p.optLong("id")<=9007199254740991L&&Arrays.asList("demo","wikimapia").contains(p.optString("source","wikimapia"));}
 public synchronized void toggle(Place p)throws Exception {boolean exists=false;JSONArray a=favorites();for(int i=0;i<a.length();i++)if(a.getJSONObject(i).optLong("id")==p.id&&a.getJSONObject(i).optString("source").equals("wikimapia"))exists=true;sync(new JSONArray(),new JSONArray().put(new JSONObject().put("remove",exists).put("place",new JSONObject().put("id",p.id).put("title",p.title).put("source","wikimapia"))),false);}
 public synchronized List<Place> cached(){Map<Long,Place> out=new LinkedHashMap<>();JSONArray a=array("areas");long now=System.currentTimeMillis();for(int i=0;i<a.length();i++)try{JSONObject r=a.getJSONObject(i);if(!r.optBoolean("pinned")&&now-r.optLong("updated")>state.optInt("retentionDays",1)*86400000L)continue;JSONArray list=r.getJSONObject("state").getJSONArray("places");for(int j=0;j<list.length();j++){Place p=Place.contour(list.getJSONObject(j));out.put(p.id,p);}}catch(Exception ignored){}return new ArrayList<>(out.values());}
 public synchronized JSONArray areas(){try{return new JSONArray(array("areas").toString());}catch(Exception e){return new JSONArray();}}
 public synchronized JSONObject fresh(double[] b){long now=System.currentTimeMillis();JSONArray a=array("areas");for(int i=a.length()-1;i>=0;i--)try{JSONObject r=a.getJSONObject(i);JSONArray box=r.getJSONArray("bbox");if(now>=r.getLong("updated")&&now-r.getLong("updated")<300000&&box.getDouble(0)<=b[0]&&box.getDouble(1)<=b[1]&&box.getDouble(2)>=b[2]&&box.getDouble(3)>=b[3])return new JSONObject(r.toString());}catch(Exception ignored){}return null;}
 public synchronized void putArea(JSONObject r)throws Exception {JSONObject before=new JSONObject(state.toString());try{JSONArray b=r.getJSONArray("bbox");double[] box=new double[4];for(int i=0;i<4;i++)box[i]=b.getDouble(i);Geo.validateBox(box);JSONArray clean=new JSONArray(),raw=r.getJSONObject("state").getJSONArray("places");for(int i=0;i<raw.length();i++)clean.put(Place.contour(raw.getJSONObject(i)).contour());JSONObject safe=new JSONObject().put("bbox",b).put("id",b.toString()).put("updated",Math.min(System.currentTimeMillis(),r.getLong("updated"))).put("pinned",r.optBoolean("pinned")).put("state",new JSONObject().put("places",clean).put("page",r.getJSONObject("state").optInt("page",1)).put("more",r.getJSONObject("state").optBoolean("more")).put("complete",r.getJSONObject("state").optBoolean("complete")));
 List<JSONObject> rows=new ArrayList<>();JSONArray old=array("areas");for(int i=0;i<old.length();i++){JSONObject o=old.getJSONObject(i);if(!o.getJSONArray("bbox").toString().equals(b.toString()))rows.add(o);else if(o.optLong("updated")>safe.optLong("updated"))return;else safe.put("pinned",safe.optBoolean("pinned")||o.optBoolean("pinned"));}rows.add(safe);rows.sort((x,y)->{int p=Boolean.compare(y.optBoolean("pinned"),x.optBoolean("pinned"));return p!=0?p:Long.compare(y.optLong("updated"),x.optLong("updated"));});JSONArray keep=new JSONArray();int bytes=0;for(JSONObject o:rows){int n=o.toString().getBytes(StandardCharsets.UTF_8).length;if(keep.length()<32&&bytes+n<=12*1024*1024){keep.put(o);bytes+=n;}else if(o.optBoolean("pinned"))throw new IOException("Недостаточно места для закреплённых контуров");}state.put("areas",keep);save();}catch(Exception e){state=before;throw e;}}
 public synchronized JSONObject cache(String action,JSONObject options)throws Exception {
  JSONObject before=new JSONObject(state.toString());try{
   if(!state.optBoolean("cacheMigrated")){
    JSONArray legacy=options.optJSONArray("legacy");if(legacy!=null){for(int i=0;i<legacy.length();i++)try{putArea(legacy.getJSONObject(i));}catch(IllegalArgumentException ignored){}state.put("cacheMigrated",true);}
   }
   JSONArray rows=areas();
   if(action.equals("put")){putArea(options.getJSONObject("entry"));rows=areas();}
   if(action.equals("preferences")){int days=options.optInt("retentionDays",1);if(days!=1&&days!=7&&days!=30)days=1;state.put("retentionDays",days);}
   if(action.equals("pin")){JSONArray ids=options.getJSONArray("ids");Set<String> wanted=new HashSet<>();for(int i=0;i<ids.length();i++)wanted.add(ids.getString(i));Set<String> found=new HashSet<>();for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);JSONArray b=r.getJSONArray("bbox");String id=b.get(0)+","+b.get(1)+","+b.get(2)+","+b.get(3);if(wanted.contains(id)||wanted.contains(r.optString("id"))){r.put("pinned",options.optBoolean("pinned"));found.add(id);}}if(found.size()!=wanted.size())throw new IOException("Область ещё не сохранена");state.put("areas",rows);}
   JSONArray kept=new JSONArray();int bytes=0,pinned=0;long now=System.currentTimeMillis();int days=state.optInt("retentionDays",1);
   for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);if(action.equals("clear")&&(options.optBoolean("includePinned")||!r.optBoolean("pinned")))continue;if(!r.optBoolean("pinned")&&(r.optLong("updated")>now||now-r.optLong("updated")>=days*86400000L))continue;JSONArray b=r.getJSONArray("bbox");r.put("id",b.get(0)+","+b.get(1)+","+b.get(2)+","+b.get(3));int n=r.toString().getBytes(StandardCharsets.UTF_8).length;r.put("bytes",n).put("retentionDays",days);kept.put(r);bytes+=n;if(r.optBoolean("pinned"))pinned++;}
   state.put("areas",kept);save();return new JSONObject().put("entries",kept).put("count",kept.length()).put("bytes",bytes).put("pinnedCount",pinned).put("preferences",new JSONObject().put("retentionDays",days)).put("saved",true);
  }catch(Exception e){state=before;save();throw e;}
 }
 public synchronized void viewport(Viewport v,long selected)throws Exception{state.put("lat",v.lat).put("lon",v.lon).put("zoom",v.zoom).put("selected",selected);save();}
 public synchronized Viewport viewport(){return new Viewport(state.optDouble("lat",55.752),state.optDouble("lon",37.618),state.optDouble("zoom",16));}
 public synchronized long selected(){return state.optLong("selected",0);}
 public synchronized void pending(long id)throws Exception{state.put("pending",id);save();}
 public synchronized long consumePending()throws Exception{long id=state.optLong("pending");state.remove("pending");save();return id;}
}
